/**
 * Turns a {@link FragmentIR} into an executable {@link LongPredicateFragment}. The most common one-node shapes get
 * hand-written precompiled primitives — the InkFuse "free interpreter" move: zero definition cost, monomorphic bodies,
 * no codegen. Everything else runs through the {@link FragmentInterpreter} (always correct, always available). Both
 * backends implement identical semantics; the differential tests pin the primitives to the interpreter.
 *
 * <p>
 * Compiled fragments are immutable and stateless, so they are cached process-wide by structural
 * {@link FragmentIR#shapeKey()} in a bounded LRU. Bindings are never cached.
 */
public final class FragmentCompiler {

	private static final int CACHE_CAPACITY = 512;

	private static final Map<String, LongPredicateFragment> CACHE = new LinkedHashMap<>(64, 0.75f, true) {
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, LongPredicateFragment> eldest) {
			return size() > CACHE_CAPACITY;
		}
	};

	private FragmentCompiler() {
	}

	/** Compiles (or serves from the shape-keyed cache) an executable form of a predicate fragment. */
	public static LongPredicateFragment compilePredicate(FragmentIR ir) {
		if (ir.resultKind() != FragmentResultKind.PREDICATE) {
			throw new IllegalArgumentException("not a predicate fragment: " + ir);
		}
		synchronized (CACHE) {
			LongPredicateFragment cached = CACHE.get(ir.shapeKey());
			if (cached != null) {
				return cached;
			}
		}
		LongPredicateFragment compiled = compile(ir);
		synchronized (CACHE) {
			CACHE.putIfAbsent(ir.shapeKey(), compiled);
		}
		return compiled;
	}

	private static LongPredicateFragment compile(FragmentIR ir) {
		LongPredicateFragment primitive = primitiveFor(ir.root());
		if (primitive != null) {
			return primitive;
		}
		return (a0, a1, a2, binding) -> FragmentInterpreter.testPredicate(ir, a0, a1, a2, binding);
	}

	private static LongPredicateFragment primitiveFor(FragmentNode root) {
		if (root instanceof IsBound isBound && isBound.input()instanceof Argument argument) {
			int index = argument.index();
			return (a0, a1, a2, binding) -> argumentAt(index, a0, a1, a2) != -1L
					? PredicateStatus.TRUE
					: PredicateStatus.FALSE;
		}
		if (root instanceof TypeGuard guard && guard.input()instanceof Argument argument) {
			int index = argument.index();
			IdCapability capability = guard.capability();
			return (a0, a1, a2, binding) -> capability.test(argumentAt(index, a0, a1, a2))
					? PredicateStatus.TRUE
					: PredicateStatus.FALSE;
		}
		if (root instanceof Compare compare) {
			LongPredicateFragment comparePrimitive = comparePrimitive(compare);
			if (comparePrimitive != null) {
				return comparePrimitive;
			}
		}
		if (root instanceof SameTerm sameTerm) {
			LongPredicateFragment identity = sameTermPrimitive(sameTerm);
			if (identity != null) {
				return identity;
			}
		}
		if (root instanceof BooleanAnd and && and.left()instanceof Compare lower
				&& and.right()instanceof Compare upper) {
			LongPredicateFragment range = orderedRangePrimitive(lower, upper);
			if (range != null) {
				return range;
			}
		}
		return null;
	}

	private static LongPredicateFragment comparePrimitive(Compare compare) {
		// ordered-integer compare against a bound constant: the Q1 fast path
		if (compare.left()instanceof DecodeInline left && compare.right()instanceof DecodeInline right
				&& left.kind() == DecodeInline.InlineKind.ORDERED_INTEGER
				&& right.kind() == DecodeInline.InlineKind.ORDERED_INTEGER) {
			if (left.input()instanceof Argument argument && right.input()instanceof Constant constant) {
				return orderedCompareToConstant(argument.index(), constant.slot(), compare.op(), false);
			}
			if (left.input()instanceof Constant constant && right.input()instanceof Argument argument) {
				return orderedCompareToConstant(argument.index(), constant.slot(), compare.op().flip(), true);
			}
			if (left.input()instanceof Argument leftArgument && right.input()instanceof Argument rightArgument) {
				return orderedCompareArguments(leftArgument.index(), rightArgument.index(), compare.op());
			}
			return null;
		}
		// raw-id term compare: identity-aware EQ/NE plus ordered-integer numeric order
		if (compare.left()instanceof Argument leftArgument) {
			if (compare.right()instanceof Constant constant) {
				return rawIdCompare(leftArgument.index(), -1, constant.slot(), compare.op());
			}
			if (compare.right()instanceof Argument rightArgument) {
				return rawIdCompare(leftArgument.index(), rightArgument.index(), -1, compare.op());
			}
		}
		if (compare.left()instanceof Constant constant && compare.right()instanceof Argument rightArgument) {
			return rawIdCompare(rightArgument.index(), -1, constant.slot(), compare.op().flip());
		}
		return null;
	}

	/** Term identity over raw ids: exactly {@link FragmentInterpreter}'s SameTerm semantics, monomorphic. */
	private static LongPredicateFragment sameTermPrimitive(SameTerm sameTerm) {
		if (sameTerm.left()instanceof Argument leftArgument) {
			if (sameTerm.right()instanceof Argument rightArgument) {
				return sameTermIdentity(leftArgument.index(), rightArgument.index(), -1);
			}
			if (sameTerm.right()instanceof Constant constant) {
				return sameTermIdentity(leftArgument.index(), -1, constant.slot());
			}
		}
		if (sameTerm.left()instanceof Constant constant && sameTerm.right()instanceof Argument rightArgument) {
			return sameTermIdentity(rightArgument.index(), -1, constant.slot());
		}
		return null;
	}

	private static LongPredicateFragment sameTermIdentity(int leftIndex, int rightArgumentIndex,
			int rightConstantSlot) {
		return (a0, a1, a2, binding) -> {
			long left = argumentAt(leftIndex, a0, a1, a2);
			long right = rightArgumentIndex >= 0 ? argumentAt(rightArgumentIndex, a0, a1, a2)
					: binding.constants[rightConstantSlot];
			if (left == -1L || right == -1L) {
				return PredicateStatus.ERROR;
			}
			return left == right ? PredicateStatus.TRUE : PredicateStatus.FALSE;
		};
	}

	private static LongPredicateFragment orderedCompareToConstant(int argumentIndex, int constantSlot,
			FragmentCompareOp op, boolean constantOnLeft) {
		// Mirrors the interpreter's left-operand-first evaluation so ERROR/ESCAPE precedence matches exactly.
		return (a0, a1, a2, binding) -> {
			long id = argumentAt(argumentIndex, a0, a1, a2);
			long constant = binding.constants[constantSlot];
			long first = constantOnLeft ? constant : id;
			long second = constantOnLeft ? id : constant;
			if (first == -1L) {
				return PredicateStatus.ERROR;
			}
			if (!ValueIds.isOrderedInteger(first)) {
				return PredicateStatus.ESCAPE;
			}
			if (second == -1L) {
				return PredicateStatus.ERROR;
			}
			if (!ValueIds.isOrderedInteger(second)) {
				return PredicateStatus.ESCAPE;
			}
			return op.test(ValueIds.compareOrderedIntegers(id, constant)) ? PredicateStatus.TRUE
					: PredicateStatus.FALSE;
		};
	}

	private static LongPredicateFragment orderedCompareArguments(int leftIndex, int rightIndex, FragmentCompareOp op) {
		return (a0, a1, a2, binding) -> {
			// left operand first, mirroring the interpreter's ERROR/ESCAPE precedence
			long left = argumentAt(leftIndex, a0, a1, a2);
			if (left == -1L) {
				return PredicateStatus.ERROR;
			}
			if (!ValueIds.isOrderedInteger(left)) {
				return PredicateStatus.ESCAPE;
			}
			long right = argumentAt(rightIndex, a0, a1, a2);
			if (right == -1L) {
				return PredicateStatus.ERROR;
			}
			if (!ValueIds.isOrderedInteger(right)) {
				return PredicateStatus.ESCAPE;
			}
			return op.test(ValueIds.compareOrderedIntegers(left, right)) ? PredicateStatus.TRUE : PredicateStatus.FALSE;
		};
	}

	/** Term comparison over raw ids: exactly {@link FragmentInterpreter}'s semantics, monomorphic. */
	private static LongPredicateFragment rawIdCompare(int leftIndex, int rightArgumentIndex, int rightConstantSlot,
			FragmentCompareOp op) {
		return (a0, a1, a2, binding) -> {
			long left = argumentAt(leftIndex, a0, a1, a2);
			long right = rightArgumentIndex >= 0 ? argumentAt(rightArgumentIndex, a0, a1, a2)
					: binding.constants[rightConstantSlot];
			if (left == -1L || right == -1L) {
				return PredicateStatus.ERROR;
			}
			if (ValueIds.isOrderedInteger(left) && ValueIds.isOrderedInteger(right)) {
				return op.test(ValueIds.compareOrderedIntegers(left, right)) ? PredicateStatus.TRUE
						: PredicateStatus.FALSE;
			}
			if (op == FragmentCompareOp.EQ || op == FragmentCompareOp.NE) {
				if (left == right && !ValueIds.isDouble(left)) {
					return op == FragmentCompareOp.EQ ? PredicateStatus.TRUE : PredicateStatus.FALSE;
				}
				if (IdCapability.IDENTITY_SAFE.test(left) && IdCapability.IDENTITY_SAFE.test(right)) {
					return op == FragmentCompareOp.EQ ? PredicateStatus.FALSE : PredicateStatus.TRUE;
				}
			}
			return PredicateStatus.ESCAPE;
		};
	}

	/**
	 * {@code lo <= arg && arg < hi}-style ranges over one ordered-integer argument fold into a single primitive with
	 * one decode; any bound combination of GE/GT and LE/LT over the same argument qualifies.
	 */
	private static LongPredicateFragment orderedRangePrimitive(Compare lower, Compare upper) {
		if (!(lower.left()instanceof DecodeInline lowerLeft && lower.right()instanceof DecodeInline lowerRight
				&& upper.left()instanceof DecodeInline upperLeft && upper.right()instanceof DecodeInline upperRight)) {
			return null;
		}
		if (lowerLeft.kind() != DecodeInline.InlineKind.ORDERED_INTEGER
				|| lowerRight.kind() != DecodeInline.InlineKind.ORDERED_INTEGER
				|| upperLeft.kind() != DecodeInline.InlineKind.ORDERED_INTEGER
				|| upperRight.kind() != DecodeInline.InlineKind.ORDERED_INTEGER) {
			return null;
		}
		if (!(lowerLeft.input()instanceof Argument lowerArgument && lowerRight.input()instanceof Constant lowerConstant
				&& upperLeft.input()instanceof Argument upperArgument
				&& upperRight.input()instanceof Constant upperConstant)) {
			return null;
		}
		if (lowerArgument.index() != upperArgument.index()) {
			return null;
		}
		int argumentIndex = lowerArgument.index();
		int lowerSlot = lowerConstant.slot();
		int upperSlot = upperConstant.slot();
		FragmentCompareOp lowerOp = lower.op();
		FragmentCompareOp upperOp = upper.op();
		return (a0, a1, a2, binding) -> {
			long id = argumentAt(argumentIndex, a0, a1, a2);
			if (id == -1L) {
				// both compares are type errors: E && E = E
				return PredicateStatus.ERROR;
			}
			long lowerId = binding.constants[lowerSlot];
			long upperId = binding.constants[upperSlot];
			// Per-side statuses composed with three-valued AND, exactly as the interpreter would: a decided FALSE on
			// either side wins over an ESCAPE/ERROR on the other.
			PredicateStatus lowerStatus = orderedSideStatus(id, lowerId, lowerOp);
			if (lowerStatus == PredicateStatus.FALSE) {
				return PredicateStatus.FALSE;
			}
			PredicateStatus upperStatus = orderedSideStatus(id, upperId, upperOp);
			if (upperStatus == PredicateStatus.FALSE) {
				return PredicateStatus.FALSE;
			}
			if (lowerStatus == PredicateStatus.ESCAPE || upperStatus == PredicateStatus.ESCAPE) {
				return PredicateStatus.ESCAPE;
			}
			if (lowerStatus == PredicateStatus.ERROR || upperStatus == PredicateStatus.ERROR) {
				return PredicateStatus.ERROR;
			}
			return PredicateStatus.TRUE;
		};
	}

	private static PredicateStatus orderedSideStatus(long id, long constant, FragmentCompareOp op) {
		// argument is the left operand in the recognized range shape: its ESCAPE precedes the constant's status
		if (!ValueIds.isOrderedInteger(id)) {
			return PredicateStatus.ESCAPE;
		}
		if (constant == -1L) {
			return PredicateStatus.ERROR;
		}
		if (!ValueIds.isOrderedInteger(constant)) {
			return PredicateStatus.ESCAPE;
		}
		return op.test(ValueIds.compareOrderedIntegers(id, constant)) ? PredicateStatus.TRUE : PredicateStatus.FALSE;
	}

	private static long argumentAt(int index, long a0, long a1, long a2) {
		switch (index) {
		case 0:
			return a0;
		case 1:
			return a1;
		default:
			return a2;
		}
	}
}
